    "for i in range(3):\\n",
    "    templates[i] = np.outer(np.sin(np.linspace(0, (i+1)*np.pi, 8)), np.cos(np.linspace(0, (i+1)*np.pi, 8)))\\n",
    "    \\n",
    "for i in range(3):\\n",
    "    ax = plt.subplot(1, 3, i+1) if i > 0 else axes[1]\\n",
    "    \\n",
    "# Use subplot approach\\n",
    "fig2, axes2 = plt.subplots(1, 3, figsize=(10, 3))\\n",
    "for i in range(3):\\n",
    "    im = axes2[i].imshow(templates[i], cmap='RdBu', vmin=-1, vmax=1)\\n",
