    "        clf.train_step(X_train_bias, y_train)\\n",
    "    train_accs_sm.append(clf.accuracy(X_train_bias, y_train))\\n",
    "    test_accs_sm.append(clf.accuracy(X_test_bias, y_test))\\n",
    "\\n",
    "x_pos = np.arange(len(reg_strengths))\\n",
    "width = 0.35\\n",
